mapper.select:
SELECT task_id, task_name, task_type, submitted_by, submit_time, start_time, end_time, original_filename, file_path, result_file_path, status, total_books, sensitive_hits, problem_book_hits, non_whitelist_pubs, total_problem_books, error_message, created_time, update_time FROM booklist_check_task
AND task_name ILIKE CONCAT('%', #{taskName}, '%')
AND status = #{status}
AND submitted_by = #{submittedBy}
ORDER BY submit_time DESC
